":_theme=ThemeMinimal();break;case"pm":_theme=ThemePM();break;default:_theme=ThemeDefault();break;}}int[]ParseBackupPriority(string s){var parts=s.ToLower().Split(',');var result=new List<int>();for(int i=0;i<parts.Length;i++){string p=parts[i].Trim();if(p=="reactor"&&!result.Contains(0))result.Add(0);else if((p=="h2"||p=="hydrogen")&&!result.Contains(1))result.Add(1);}if(result.Count==0)result.Add(0);return result.ToArray();}void MigrateConfig(MyIni ini,int fromVer){ini.Set(SECTION,K_CFG_VER,CURRENT_CFG_VER);Me.CustomData=ini.ToString();_lastCustomData=Me.CustomData;SetBanner("Config migrated to v"+CURRENT_CFG_VER);}void WriteDefaults(MyIni ini){ini.Set(SECTION,K_DISP_TAG,_displayTag);ini.SetComment(SECTION,K_DISP_TAG," Tag in block name for power displays. Use :N for surface index (e.g. [POWER:1])");ini.Set(SECTION,K_ALERT_TAG,_alertTag);ini.SetComment(SECTION,K_ALERT_TAG," Tag for alert lights. Append :type to filter (e.g. [PowerAlert:fuel,battery])");ini.Set(SECTION,K_LIGHT_TAG,_lightTag);ini.SetComment(SECTION,K_LIGHT_TAG," Tag for day/night auto-controlled lights");ini.Set(SECTION,K_IGNORE_TAG,_ignoreTag);ini.SetComment(SECTION,K_IGNORE_TAG," Tag to exclude a block from all script control");ini.Set(SECTION,K_ALERT_GROUP,_alertGroup);ini.SetComment(SECTION,K_ALERT_GROUP," Optional block group name for alert lights (empty = disabled)");ini.Set(SECTION,K_LIGHT_GROUP,_lightGroup);ini.SetComment(SECTION,K_LIGHT_GROUP," Optional block group name for day/night lights (empty = disabled)");ini.Set(SECTION,K_RESCAN,_rescanSecs);ini.SetComment(SECTION,K_RESCAN," Seconds between automatic block rescans (5-600)");ini.Set(SECTION,K_LOW_U,_lowUranium);ini.SetComment(SECTION,K_LOW_U," Uranium (kg) below which the low fuel alert triggers");ini.Set(SECTION,K_LOW_BAT,_lowBatPct);ini.SetComment(SECTION,K_LOW_BAT," Battery % below which the critical battery alert triggers");ini.Set(SECTION,K_LOW_H2,_lowH2Pct);ini.SetComment(SECTION,K_LOW_H2," H2 tank % below which the low hydrogen