ini.Set(SECTION,K_BLINK,_blinkDuration);ini.SetComment(SECTION,K_BLINK," Seconds to blink lights on reactor/H2 state change (1-120)");ini.Set(SECTION,K_STACK,_stackAlerts);ini.SetComment(SECTION,K_STACK," true = cycle alert colors when multiple alerts active; false = show highest priority only");ini.Set(SECTION,K_ESC_SLOW,_escSlowSecs);ini.SetComment(SECTION,K_ESC_SLOW," Seconds before alert escalates to slow blink");ini.Set(SECTION,K_ESC_FAST,_escFastSecs);ini.SetComment(SECTION,K_ESC_FAST," Seconds before alert escalates to fast blink");ini.Set(SECTION,K_NIGHT_THR,_nightThr);ini.SetComment(SECTION,K_NIGHT_THR," Solar output % below which it is considered night (lights ON)");ini.Set(SECTION,K_DAY_THR,_dayThr);ini.SetComment(SECTION,K_DAY_THR," Solar output % above which it is considered day (lights OFF)");ini.Set(SECTION,K_BACKUP_PRI,_backupPriStr);ini.SetComment(SECTION,K_BACKUP_PRI," Backup power priority order: reactor, h2 (comma-separated)");ini.Set(SECTION,K_T1_ON,_t1On);ini.SetComment(SECTION,K_T1_ON," Battery % at which the first backup source turns ON");ini.Set(SECTION,K_T1_OFF,_t1Off);ini.SetComment(SECTION,K_T1_OFF," Battery % at which the first backup source turns OFF");ini.Set(SECTION,K_T2_ON,_t2On);ini.SetComment(SECTION,K_T2_ON," Battery % at which the second backup source turns ON (if configured)");ini.Set(SECTION,K_T2_OFF,_t2Off);ini.SetComment(SECTION,K_T2_OFF," Battery % at which the second backup source turns OFF (if configured)");ini.Set(SECTION,K_WIND_SUB,_windSubs);ini.SetComment(SECTION,K_WIND_SUB," Subtypes to identify wind turbines (comma-separated, for mod support)");ini.Set(SECTION,K_H2_SUB,_h2Subs);ini.SetComment(SECTION,K_H2_SUB," Subtypes to identify H2 engines (comma-separated, for mod support)");ini.Set(SECTION,K_IGNORE_SUB,_ignoreSubs);ini.SetComment(SECTION,K_IGNORE_SUB," Subtypes to ignore when classifying power producers (comma-separated)");ini.Set(SECTION,K_THEME,_themeName);ini.SetComment(SECTION,K_THEME," Display theme: defaul